  1132→// replaceTranscript writes the full transcript content, replacing any existing transcript.
  1133→// Also removes any chunk files from a previous write and updates the content hash.
  1134→func (s *GitStore) replaceTranscript(transcript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
  1135→	// Remove existing transcript files (base + any chunks)
  1136→	transcriptBase := sessionPath + paths.TranscriptFileName
  1137→	for key := range entries {
  1138→		if key == transcriptBase || strings.HasPrefix(key, transcriptBase+".") {
  1139→			delete(entries, key)
  1140→		}
  1141→	}
  1142→
  1143→	// Write new transcript blob
  1144→	blobHash, err := CreateBlobFromContent(s.repo, transcript)
  1145→	if err != nil {
  1146→		return fmt.Errorf("failed to create transcript blob: %w", err)
  1147→	}
  1148→	entries[transcriptBase] = object.TreeEntry{
  1149→		Name: transcriptBase,
  1150→		Mode: filemode.Regular,
  1151→		Hash: blobHash,
  1152→	}
  1153→
  1154→	// Update content hash
  1155→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
  1156→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
  1157→	if err != nil {
  1158→		return fmt.Errorf("failed to create content hash blob: %w", err)
  1159→	}
  1160→	hashPath := sessionPath + paths.ContentHashFileName
  1161→	entries[hashPath] = object.TreeEntry{
  1162→		Name: hashPath,
  1163→		Mode: filemode.Regular,
  1164→		Hash: hashBlob,
  1165→	}
  1166→
  1167→	return nil
  1168→}
