  1368→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
  1369→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
  1370→// The agentType is used for reassembling chunks in the correct format.
  1371→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
  1372→	// Collect all transcript-related files
  1373→	var chunkFiles []string
  1374→	var hasBaseFile bool
  1375→
  1376→	for _, entry := range tree.Entries {
  1377→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
  1378→			hasBaseFile = true
  1379→		}
  1380→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
  1381→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
  1382→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
  1383→			if idx > 0 {
  1384→				chunkFiles = append(chunkFiles, entry.Name)
  1385→			}
  1386→		}
  1387→	}
  1388→
  1389→	// If we have chunk files, read and reassemble them
  1390→	if len(chunkFiles) > 0 {
  1391→		// Sort chunk files by index
  1392→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
  1393→
  1394→		// Check if base file should be included as chunk 0.
  1395→		// NOTE: This assumes the chunking convention where the unsuffixed file
  1396→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
  1397→		if hasBaseFile {
  1398→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
  1399→		}
  1400→
  1401→		var chunks [][]byte
  1402→		for _, chunkFile := range chunkFiles {
  1403→			file, err := tree.File(chunkFile)
  1404→			if err != nil {
  1405→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
  1406→					slog.String("chunk_file", chunkFile),
  1407→					slog.String("error", err.Error()),
  1408→				)
  1409→				continue
  1410→			}
  1411→			content, err := file.Contents()
  1412→			if err != nil {
  1413→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
  1414→					slog.String("chunk_file", chunkFile),
  1415→					slog.String("error", err.Error()),
  1416→				)
  1417→				continue
  1418→			}
  1419→			chunks = append(chunks, []byte(content))
  1420→		}
  1421→
  1422→		if len(chunks) > 0 {
  1423→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1424→			if err != nil {
  1425→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1426→			}
  1427→			return result, nil
  1428→		}
  1429→	}
  1430→
  1431→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1432→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1433→		if content, err := file.Contents(); err == nil {
  1434→			return []byte(content), nil
  1435→		}
  1436→	}
  1437→
  1438→	// Try legacy filename
  1439→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1440→		if content, err := file.Contents(); err == nil {
  1441→			return []byte(content), nil
  1442→		}
  1443→	}
  1444→
  1445→	return nil, nil
  1446→}
